mapper.delete:
DELETE FROM test_case_task
WHERE workspace_id = #{workspaceId}
  AND case_id IN
  #{id}

DELETE FROM test_case_task
WHERE workspace_id = #{workspaceId}
  AND task_id IN
  #{id}

DELETE ct FROM test_case_task ct
JOIN task t ON t.id = ct.task_id AND t.workspace_id = ct.workspace_id
WHERE ct.workspace_id = #{workspaceId} AND t.demand_id = #{demandId}

DELETE ct FROM test_case_task ct
JOIN test_case c ON c.id = ct.case_id AND c.workspace_id = ct.workspace_id
WHERE ct.workspace_id = #{workspaceId} AND c.req_id = #{reqId}

mapper.select:
SELECT * FROM test_case_task
WHERE workspace_id = #{workspaceId}
ORDER BY created_at, id

SELECT NULL AS case_id, t.id AS task_id, t.title AS task_title, t.item_type, t.board_column,
       t.demand_id, t.item_no
FROM task t
WHERE t.workspace_id = #{workspaceId}
  AND t.req_id = #{reqId}
  AND t.demand_id = #{demandId}
  AND t.deleted_at IS NULL

  AND (t.title LIKE CONCAT('%', #{q}, '%')
       OR t.item_no = #{itemNo})

ORDER BY t.item_no IS NULL, t.item_no, t.created_at, t.id
LIMIT #{limit}
